import { Group, Mesh, MeshStandardMaterial, AmbientLight, DirectionalLight } from 'three/webgpu';
import gsap from 'gsap';

/**
 * Creates a thumbnail card for the home hub.
 * Loads a GLB gear mesh, applies interactive hover lift and press-down click behavior.
 * 
 * @param {Object} config - Node configuration (scenePosition, userData, etc.)
 * @param {Object} ctx - Context with loaders and utilities
 * @returns {THREE.Group} The card group with userData.handlers and cleanup
 */
export default function createNode(config, ctx) {
  const group = new Group();

  // --- Load GLB mesh (synchronous, cached) ---
  const { scene: gearScene, animations } = ctx.glbLoader.get('/prism-mock/orrery/meshes/gear-a.glb');
  const gearChild = gearScene.clone(true); // clone for safe disposal
  group.add(gearChild);

  // --- Position, rotation, scale from config ---
  const pos = config.scenePosition?.position || { x: -2.5, y: -0.2, z: 0 };
  const rot = config.scenePosition?.rotation || { x: 0, y: 0, z: 0 };
  const scl = config.scenePosition?.scale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  // --- Wrap for consistent event target ---
  const hitTarget = new Group();
  // Re-parent to ensure children are under hitTarget
  while (group.children.length > 0) {
    hitTarget.add(group.children[0]);
  }
  group.add(hitTarget);

  // --- Store pointers for cleanup ---
  let hoverTimeline = null;
  let clickTimeline = null;

  // --- Interaction handlers ---
  const handlers = {
    pointerover: () => {
      // Rise-in: move y up by 0.15 scene units
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(hitTarget.position, {
        y: 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    },
    pointerout: () => {
      // Return to original y (0 relative to group)
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(hitTarget.position, {
        y: 0,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    },
    click: () => {
      // Press-down then back, then emit
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.timeline({
        onComplete: () => {
          if (typeof window !== 'undefined' && window.dispatchEvent) {
            window.dispatchEvent(new CustomEvent('hub-home.select', { detail: { source: 'thumbnail' } }));
          }
        }
      });
      clickTimeline.to(hitTarget.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out'
      })
      .to(hitTarget.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.2,
        ease: 'power2.out'
      });
    }
  };

  // Attach handlers to the group's userData (not to DOM)
  group.userData.handlers = handlers;

  // Ensure hitTarget also has pointer events (Three.js raycasting will use group children)
  // We'll add a simple invisible plane or use the mesh's bounding box? For simplicity, we rely on the
  // mesh's geometry for raycasting. If the mesh doesn't have a geometry, we could add a box helper.
  // But typical GLB has geometry.

  // --- Cleanup ---
  const cleanup = () => {
    // Kill GSAP timelines
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();

    // Dispose of all mesh geometries and materials in the cloned scene
    gearChild.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  };
  group.userData.cleanup = cleanup;

  return group;
}
